function kthFromTop(nums: number[], k: number): number {
  const a = nums.slice();
  const target = a.length - k; // index of the answer in ascending order
  let lo = 0, hi = a.length - 1;
  for (;;) {
    const p = a[lo + Math.floor(Math.random() * (hi - lo + 1))];
    // three-way partition of a[lo..hi]: [< p][== p][> p]
    let lt = lo, i = lo, gt = hi;
    while (i <= gt) {
      if (a[i] < p) { [a[lt], a[i]] = [a[i], a[lt]]; lt++; i++; }
      else if (a[i] > p) { [a[i], a[gt]] = [a[gt], a[i]]; gt--; }
      else i++;
    }
    if (target < lt) hi = lt - 1;
    else if (target > gt) lo = gt + 1;
    else return p;
  }
}

