import random


class Solution:
    def kthFromTop(self, nums: List[int], k: int) -> int:
        while True:
            p = random.choice(nums)
            greater = [x for x in nums if x > p]
            if k <= len(greater):
                nums = greater
                continue
            equal = nums.count(p)
            if k <= len(greater) + equal:
                return p
            k -= len(greater) + equal
            nums = [x for x in nums if x < p]

